python3 - <<'EOF'
import re
from collections import Counter
for f in ['docs/spec-audit-durability.tex','docs/spec-hook-gates.tex','docs/spec-mission-lifecycle.tex','docs/spec-writeset-admission.tex']:
    s = open(f).read()
    labels = re.findall(r'\\label\{([^}]*)\}', s)
    refs = re.findall(r'\\(?:ref|autoref|eqref|pageref)\{([^}]*)\}', s)
    dup = {l for l in labels if labels.count(l) > 1}
    missing = {r for r in refs if r not in labels}
    cb, ce = Counter(re.findall(r'\\begin\{([^}]*)\}', s)), Counter(re.findall(r'\\end\{([^}]*)\}', s))
    unb = {k: (cb[k], ce[k]) for k in set(cb)|set(ce) if cb[k] != ce[k]}
    print(f, '| dup', dup or '-', '| missingref', missing or '-', '| unbalanced', unb or '-')
    # math-only macros inside \field{} or plain text
    for i, line in enumerate(s.split('\n'), 1):
        if re.search(r'\\field\{[^}]*\\(Xi|Delta|emptyset|in|neq|land|lnot|dom|seq)\b', line):
            print('   MATH-IN-FIELD', i, line.strip()[:100])
EOF
